#!/usr/bin/env bash
# L3 (plan §8.1, P0-06): Android emulator + netsim virtual radio + Bumble test peripheral.
#
# Starts the Bumble peripheral on the emulator's radio, runs the library's instrumented tests,
# and collects logcat, `dumpsys bluetooth_manager`, the Bumble log and the test reports.
#
# Prerequisites: one running emulator with Bluetooth (it starts netsimd itself), root
# `yarn install && yarn prepare`, `example/android` generated by `npx expo prebuild`, and uv.
# ANDROID_HOME must point at the Android SDK. Set L3_ARTIFACTS_DIR to change the output folder.
# Extra arguments go to Gradle, e.g. -Pandroid.testInstrumentationRunnerArguments.requestedMtu=247
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
OUT="${L3_ARTIFACTS_DIR:-$ROOT/e2e/android-netsim/artifacts}"
mkdir -p "$OUT"

export ANDROID_SERIAL="${ANDROID_SERIAL:-$(adb devices | awk '/^emulator-[0-9]+\tdevice/ { print $1; exit }')}"
if [ -z "$ANDROID_SERIAL" ]; then
  echo "No running emulator found (adb devices)." >&2
  exit 1
fi
echo "Emulator: $ANDROID_SERIAL"

BUMBLE_PID=""
collect() {
  local status=$?
  if [ -n "$BUMBLE_PID" ]; then
    kill "$BUMBLE_PID" 2>/dev/null || true
    wait "$BUMBLE_PID" 2>/dev/null || true
  fi
  adb logcat -d > "$OUT/logcat.txt" 2>&1 || true
  adb shell dumpsys bluetooth_manager > "$OUT/dumpsys_bluetooth_manager.txt" 2>&1 || true
  for dir in reports/androidTests outputs/androidTest-results; do
    if [ -d "$ROOT/android/build/$dir" ]; then
      mkdir -p "$OUT/$dir" && cp -R "$ROOT/android/build/$dir/." "$OUT/$dir/"
    fi
  done
  echo "Artifacts in $OUT (exit $status)"
}
trap collect EXIT

# Start the peripheral and wait until it advertises.
(cd "$ROOT/test-peripherals/bumble" && uv sync --locked --quiet)
(cd "$ROOT/test-peripherals/bumble" && exec uv run --locked blekit-peripheral android-netsim --log-level DEBUG) \
  > "$OUT/bumble.log" 2>&1 &
BUMBLE_PID=$!
for _ in $(seq 1 60); do
  grep -q "Advertising as" "$OUT/bumble.log" && break
  if ! kill -0 "$BUMBLE_PID" 2>/dev/null; then
    echo "Bumble peripheral exited early:" >&2
    tail -20 "$OUT/bumble.log" >&2
    exit 1
  fi
  sleep 1
done
grep -q "Advertising as" "$OUT/bumble.log" || { echo "Bumble peripheral did not start advertising." >&2; exit 1; }
echo "Bumble peripheral is advertising."

adb logcat -c
(cd "$ROOT/example/android" && ./gradlew :expo-ble-kit:connectedDebugAndroidTest --console=plain "$@")
